-- ----------------------------
-- Table structure for CREDIT_RULE_INFO
-- ----------------------------
CREATE TABLE "CREDIT_RULE_INFO" (
"CREDIT_RULE_ID" VARCHAR2(32 BYTE) NOT NULL ,
"CREDIT_RULE_TYPE" VARCHAR2(50 BYTE) NULL ,
"CREDIT_TAG_ID" VARCHAR2(32 BYTE) NULL ,
"AST_TYPE_1" VARCHAR2(50 BYTE) NULL ,
"AST_TYPE_2" VARCHAR2(50 BYTE) NULL ,
"AST_TYPE_3" VARCHAR2(50 BYTE) NULL ,
"AST_TYPE_4" VARCHAR2(50 BYTE) NULL ,
"AST_TYPE_5" VARCHAR2(50 BYTE) NULL ,
"ORG_TYPE" VARCHAR2(50 BYTE) NULL ,
"FINPROD_ID" VARCHAR2(50 BYTE) NULL ,
"DEDUCT_OBJ_TYPE" VARCHAR2(50 BYTE) NULL ,
"REMARK" VARCHAR2(1000 BYTE) NULL ,
"CREATE_USER" VARCHAR2(20 BYTE) NOT NULL ,
"CREATE_DEPT" VARCHAR2(32 BYTE) NULL ,
"CREATE_TIME" TIMESTAMP(6)  NOT NULL ,
"UPDATE_USER" VARCHAR2(20 BYTE) NOT NULL ,
"UPDATE_TIME" TIMESTAMP(6)  NOT NULL 
);

COMMENT ON TABLE "CREDIT_RULE_INFO" IS '额度规则';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."CREDIT_RULE_ID" IS '额度规则代码';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."CREDIT_RULE_TYPE" IS '额度规则类型,资产大类、单笔资产';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."CREDIT_TAG_ID" IS '授信标签代码';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."AST_TYPE_1" IS '资产大类';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."AST_TYPE_2" IS '资产二级分类';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."AST_TYPE_3" IS '资产三级分类';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."AST_TYPE_4" IS '资产四级分类';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."AST_TYPE_5" IS '资产五级分类';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."ORG_TYPE" IS '机构大类';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."FINPROD_ID" IS '金融产品代码';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."DEDUCT_OBJ_TYPE" IS '扣减对象';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."REMARK" IS '备注';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."CREATE_USER" IS '创建人';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."CREATE_DEPT" IS '创建部门';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."UPDATE_USER" IS '更新人';
COMMENT ON COLUMN "CREDIT_RULE_INFO"."UPDATE_TIME" IS '更新时间';

ALTER TABLE "CREDIT_RULE_INFO" ADD CHECK ("CREDIT_RULE_ID" IS NOT NULL);
ALTER TABLE "CREDIT_RULE_INFO" ADD CHECK ("CREATE_USER" IS NOT NULL);
ALTER TABLE "CREDIT_RULE_INFO" ADD CHECK ("CREATE_TIME" IS NOT NULL);
ALTER TABLE "CREDIT_RULE_INFO" ADD CHECK ("UPDATE_USER" IS NOT NULL);
ALTER TABLE "CREDIT_RULE_INFO" ADD CHECK ("UPDATE_TIME" IS NOT NULL);

ALTER TABLE "CREDIT_RULE_INFO" ADD PRIMARY KEY ("CREDIT_RULE_ID");




